package slimeknights.tconstruct.library.utils;

import com.google.errorprone.annotations.CanIgnoreReturnValue;
import net.minecraft.core.particles.ParticleTypes;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.sounds.SoundEvent;
import net.minecraft.util.Mth;
import net.minecraft.util.RandomSource;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.RelativeMovement;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.gameevent.GameEvent;
import net.minecraftforge.common.MinecraftForge;
import net.minecraftforge.event.entity.EntityTeleportEvent;
import slimeknights.tconstruct.common.Sounds;

import java.util.EnumSet;
import java.util.Set;

public class TeleportHelper {
  private static final Set<RelativeMovement> PACKET_FLAGS = EnumSet.of(RelativeMovement.X, RelativeMovement.Y, RelativeMovement.Z, RelativeMovement.X_ROT, RelativeMovement.Y_ROT);

  /** Randomly teleports an entity, mostly copied from chorus fruit */
  @CanIgnoreReturnValue
  public static boolean randomNearbyTeleport(LivingEntity living, ITeleportEventFactory factory) {
    return randomNearbyTeleport(living, factory, 16, 16);
  }

  /** Randomly teleports an entity, mostly copied from chorus fruit */
  @CanIgnoreReturnValue
  public static boolean randomNearbyTeleport(LivingEntity living, ITeleportEventFactory factory, int diameter, int chances) {
    Level level = living.level();
    if (level.isClientSide) {
      return true;
    }
    double posX = living.getX();
    double posY = living.getY();
    double posZ = living.getZ();

    RandomSource random = living.getRandom();
    float minHeight = level.getMinBuildHeight();
    float maxHeight = (level instanceof ServerLevel server ? (level.getMinBuildHeight() + server.getLogicalHeight()) : level.getMaxBuildHeight()) - 1;
    for(int i = 0; i < chances; ++i) {
      double x = posX + (random.nextDouble() - 0.5D) * diameter;
      double y = Mth.clamp(posY + (double)(random.nextInt(diameter) - 8), minHeight, maxHeight);
      double z = posZ + (random.nextDouble() - 0.5D) * diameter;
      if (living.isPassenger()) {
        living.stopRiding();
      }

      level.gameEvent(GameEvent.TELEPORT, living.position(), GameEvent.Context.of(living));
      EntityTeleportEvent event = factory.create(living, x, y, z);
      MinecraftForge.EVENT_BUS.post(event);
      if (!event.isCanceled() && living.randomTeleport(event.getTargetX(), event.getTargetY(), event.getTargetZ(), true)) {
        SoundEvent soundevent = Sounds.SLIME_TELEPORT.getSound();
        // sound where we left
        level.playSound(null, posX, posY, posZ, soundevent, living.getSoundSource(), 1.0F, 1.0F);
        // sound at destination
        living.playSound(soundevent, 1.0F, 1.0F);
        return true;
      }
    }
    return false;
  }

  /** Spawns particles around the entity for teleporting */
  private static void spawnParticles(Entity entity) {
    Level level = entity.level();
    if (level instanceof ServerLevel serverWorld) {
      for (int i = 0; i < 32; ++i) {
        serverWorld.sendParticles(ParticleTypes.PORTAL, entity.getX(), entity.getY() + level.random.nextDouble() * 2.0D, entity.getZ(), 1, level.random.nextGaussian(), 0.0D, level.random.nextGaussian(), 0);
      }
    }
  }

  /** Fires the teleport event, then teleports the player if it works */
  public static boolean tryTeleport(EntityTeleportEvent event) {
    MinecraftForge.EVENT_BUS.post(event);
    if (!event.isCanceled()) {
      // spawn particles at old location
      Entity entity = event.getEntity();
      spawnParticles(entity);

      // this logic only runs serverside, so need to use the server controller logic to move the player
      if (entity instanceof ServerPlayer playerMP) {
        playerMP.connection.teleport(event.getTargetX(), event.getTargetY(), event.getTargetZ(), playerMP.getYRot(), playerMP.getXRot(), PACKET_FLAGS);
      } else {
        entity.setPos(event.getTargetX(), event.getTargetY(), event.getTargetZ());
      }
      // particles at new location
      spawnParticles(entity);
      entity.level().playSound(null, entity.getX(), entity.getY(), entity.getZ(), Sounds.ENDERPORTING.getSound(), entity.getSoundSource(), 1f, 1f);
      return true;
    }
    return false;
  }

  /** Predicate to test if the entity can teleport, typically just fires a cancelable event */
  @FunctionalInterface
  public interface ITeleportEventFactory {
    EntityTeleportEvent create(LivingEntity entity, double x, double y, double z);
  }
}

package slimeknights.tconstruct.library.modifiers.fluid;

import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.level.material.Fluid;
import net.minecraftforge.fluids.FluidStack;
import net.minecraftforge.fluids.capability.IFluidHandler.FluidAction;
import org.jetbrains.annotations.ApiStatus.Internal;
import slimeknights.mantle.data.loadable.Loadables;
import slimeknights.mantle.data.loadable.primitive.BooleanLoadable;
import slimeknights.mantle.data.loadable.record.RecordLoadable;
import slimeknights.mantle.recipe.ingredient.FluidIngredient;
import slimeknights.tconstruct.library.modifiers.fluid.FluidEffectContext.Block;
import slimeknights.tconstruct.library.modifiers.fluid.FluidEffectContext.Entity;

import java.util.List;

/** Data class to connect fluids to fluid effects */
public record FluidEffects(FluidIngredient ingredient, List<FluidEffect<? super FluidEffectContext.Block>> blockEffects, List<FluidEffect<? super FluidEffectContext.Entity>> entityEffects, boolean hidden) {
  public static final RecordLoadable<FluidEffects> LOADABLE = RecordLoadable.create(
    FluidIngredient.LOADABLE.requiredField("fluid", e -> e.ingredient),
    FluidEffect.BLOCK_EFFECTS.list(0).defaultField("block_effects", List.of(), e -> e.blockEffects),
    FluidEffect.ENTITY_EFFECTS.list(0).defaultField("entity_effects", List.of(), e -> e.entityEffects),
    BooleanLoadable.INSTANCE.defaultField("hidden", false, false, e -> e.hidden),
    FluidEffects::new);

  /** @apiNote This constructor is internal, use either {@link slimeknights.tconstruct.library.data.tinkering.AbstractFluidEffectProvider} or JSON to instantiate. */
  @Internal
  public FluidEffects {}


  /* Fluid */

  /**
   * Checks if the recipe matches the given fluid
   * @param fluid  Fluid to test
   * @return  True if this recipe handles the given fluid
   */
  public boolean matches(Fluid fluid) {
    return ingredient.test(fluid);
  }

  /** Gets the amount of fluid needed for a single level */
  public int getAmount(Fluid fluid) {
    return ingredient.getAmount(fluid);
  }


  /* Effects present */

  /**
   * Checks if this fluid has any effects of either type
   * @see #hasBlockEffects()
   * @see #hasEntityEffects()
   */
  public boolean hasEffects() {
    return hasBlockEffects() || hasEntityEffects();
  }

  /** Checks if this fluid has any block effects */
  public boolean hasBlockEffects() {
    return !blockEffects.isEmpty();
  }

  /** Checks if this fluid has any entity effects */
  public boolean hasEntityEffects() {
    return !entityEffects.isEmpty();
  }


  /* Running effects */

  /** Runs the effects for a generic context */
  private <C extends FluidEffectContext> int apply(FluidStack fluid, float level, C context, List<FluidEffect<? super C>> effects, FluidAction action) {
    int amountPerLevel = getAmount(fluid.getFluid());
    float scale;
    if (fluid.getAmount() >= amountPerLevel * level) {
      scale = level;
    } else {
      scale = fluid.getAmount() / (float)amountPerLevel;
    }
    EffectLevel effectLevel = new EffectLevel(scale, level);
    float usedScale = 0;
    for (FluidEffect<? super C> effect : effects) {
      float newScale = effect.apply(fluid, effectLevel, context, action);
      if (newScale > usedScale) {
        usedScale = newScale;
      }
    }
    return (int)Math.ceil(amountPerLevel * Math.min(scale, usedScale));
  }

  /**
   * Applies the effect to a block
   * @param fluid    Input fluid, will not be modified
   * @param level    Level of effect to apply
   * @param context  Entity fluid context
   * @param action   If {@link FluidAction#SIMULATE}, makes no changes to the context. If {@link FluidAction#EXECUTE}, the context may be modified.
   * @return  Amount of fluid to consumed from this effect, will return 0 if no effect was performed. Note this may be slightly larger than the input fluid due to rounding.
   */
  @SuppressWarnings("UnusedReturnValue")
  public int applyToBlock(FluidStack fluid, float level, Block context, FluidAction action) {
    return apply(fluid, level, context, blockEffects, action);
  }

  /**
   * Applies the effect to an entity
   * @param fluid    Input fluid, will not be modified
   * @param level    Level of effect to apply
   * @param context  Entity fluid context
   * @param action   If {@link FluidAction#SIMULATE}, makes no changes to the context. If {@link FluidAction#EXECUTE}, the context may be modified.
   * @return  Amount of fluid to consumed from this effect, will return 0 if no effect was performed.
   */
  public int applyToEntity(FluidStack fluid, float level, Entity context, FluidAction action) {
    return apply(fluid, level, context, entityEffects, action);
  }

  /** Entry for storage in the manager */
  public record Entry(ResourceLocation name, FluidEffects effects) {
    public static final RecordLoadable<Entry> LOADABLE = RecordLoadable.create(
      Loadables.RESOURCE_LOCATION.requiredField("name", Entry::name),
      FluidEffects.LOADABLE.requiredField("effects", Entry::effects),
      Entry::new);
  }
}

package slimeknights.tconstruct.library.modifiers.fluid.general;

import net.minecraft.core.RegistryAccess;
import net.minecraft.network.chat.Component;
import net.minecraftforge.fluids.FluidStack;
import net.minecraftforge.fluids.capability.IFluidHandler.FluidAction;
import org.jetbrains.annotations.ApiStatus.Internal;
import slimeknights.mantle.data.loadable.Loadable;
import slimeknights.mantle.data.loadable.record.RecordLoadable;
import slimeknights.tconstruct.library.modifiers.fluid.EffectLevel;
import slimeknights.tconstruct.library.modifiers.fluid.FluidEffect;
import slimeknights.tconstruct.library.modifiers.fluid.FluidEffectContext;

import java.util.List;

/**
 * Fluid effect which applies all effects in a sequence, stopping once an effect fails.
 * @param <C>  Effect context type
 */
public record SequenceFluidEffect<C extends FluidEffectContext>(List<FluidEffect<? super C>> effects, RecordLoadable<SequenceFluidEffect<C>> getLoader) implements FluidEffect<C> {
  public static final RecordLoadable<SequenceFluidEffect<FluidEffectContext.Block>> BLOCK_LOADER = createLoader(FluidEffectListBuilder.BLOCK_EFFECT_LIST);
  public static final RecordLoadable<SequenceFluidEffect<FluidEffectContext.Entity>> ENTITY_LOADER = createLoader(FluidEffectListBuilder.ENTITY_EFFECT_LIST);

  /** @apiNote Internal constructor, use {@link #blocks()} or {@link #entities()} */
  @Internal
  public SequenceFluidEffect {}

  @Override
  public float apply(FluidStack fluid, EffectLevel level, C context, FluidAction action) {
    float maxApplied = 0;
    for (FluidEffect<? super C> effect : effects) {
      float applied = effect.apply(fluid, level, context, action);
      // sequence breaks at first effect that doesn't apply
      if (applied <= 0) {
        break;
      }
      if (applied > maxApplied) {
        maxApplied = applied;
      }
    }
    return maxApplied;
  }

  @Override
  public Component getDescription(RegistryAccess registryAccess) {
    // almost definitely want a book description for this, but might as well generate something useful
    return effects.stream().map(effect -> effect.getDescription(registryAccess)).reduce(MERGE_COMPONENT_LIST).orElse(Component.empty());
  }


  /** Creates a new builder for block effects */
  public static FluidEffectListBuilder<FluidEffectContext.Block,SequenceFluidEffect<FluidEffectContext.Block>> blocks() {
    return FluidEffectListBuilder.builder(list -> new SequenceFluidEffect<>(list, BLOCK_LOADER));
  }

  public static FluidEffectListBuilder<FluidEffectContext.Entity,SequenceFluidEffect<FluidEffectContext.Entity>> entities() {
    return FluidEffectListBuilder.builder(list -> new SequenceFluidEffect<>(list, ENTITY_LOADER));
  }

  /** Creates a loader for the given */
  public static <C extends FluidEffectContext> RecordLoadable<SequenceFluidEffect<C>> createLoader(Loadable<List<FluidEffect<? super C>>> effectList) {
    return RecordLoadable.withLoader(effectList.requiredField("effects", SequenceFluidEffect::effects), SequenceFluidEffect::new);
  }
}

package slimeknights.tconstruct.library.modifiers.fluid.general;

import net.minecraft.core.RegistryAccess;
import net.minecraft.network.chat.Component;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraftforge.fluids.FluidStack;
import net.minecraftforge.fluids.capability.IFluidHandler.FluidAction;
import org.jetbrains.annotations.ApiStatus.Internal;
import slimeknights.mantle.data.loadable.record.RecordLoadable;
import slimeknights.mantle.data.predicate.IJsonPredicate;
import slimeknights.mantle.data.predicate.block.BlockPredicate;
import slimeknights.mantle.data.predicate.entity.LivingEntityPredicate;
import slimeknights.tconstruct.library.json.predicate.TinkerPredicate;
import slimeknights.tconstruct.library.modifiers.fluid.EffectLevel;
import slimeknights.tconstruct.library.modifiers.fluid.FluidEffect;
import slimeknights.tconstruct.library.modifiers.fluid.FluidEffectContext;

/**
 * Fluid effect that conditions on the holder and target.
 * @apiNote This class is internal, no need to use directly. Instead, make use of the helpers in {@link slimeknights.tconstruct.library.data.tinkering.AbstractFluidEffectProvider}.
 */
@Internal
public interface ConditionalFluidEffect<C extends FluidEffectContext> extends FluidEffect<C> {
  /** Gets the effect to apply */
  FluidEffect<? super C> effect();

  /** Checks if this effect can be applied */
  boolean canApply(C context);

  @Override
  default float apply(FluidStack fluid, EffectLevel level, C context, FluidAction action) {
    return canApply(context) ? effect().apply(fluid, level, context, action) : 0;
  }

  @Override
  default Component getDescription(RegistryAccess registryAccess) {
    return effect().getDescription(registryAccess);
  }

  /** Conditional block effect */
  record Block(IJsonPredicate<BlockState> block, FluidEffect<? super FluidEffectContext.Block> effect) implements ConditionalFluidEffect<FluidEffectContext.Block> {
    public static final RecordLoadable<Block> LOADER = RecordLoadable.create(
      BlockPredicate.LOADER.defaultField("block", e -> e.block),
      FluidEffect.BLOCK_EFFECTS.requiredField("effect", e -> e.effect),
      Block::new);

    @Override
    public boolean canApply(FluidEffectContext.Block context) {
      return block.matches(context.getBlockState());
    }

    @Override
    public RecordLoadable<Block> getLoader() {
      return LOADER;
    }
  }

  /** Conditional block effect */
  record Entity(IJsonPredicate<LivingEntity> target, FluidEffect<? super FluidEffectContext.Entity> effect) implements ConditionalFluidEffect<FluidEffectContext.Entity> {
    public static final RecordLoadable<Entity> LOADER = RecordLoadable.create(
      LivingEntityPredicate.LOADER.defaultField("target", e -> e.target),
      FluidEffect.ENTITY_EFFECTS.requiredField("effect", e -> e.effect),
      Entity::new);

    @Override
    public boolean canApply(FluidEffectContext.Entity context) {
      return TinkerPredicate.matches(target, context.getLivingTarget());
    }

    @Override
    public RecordLoadable<Entity> getLoader() {
      return LOADER;
    }
  }
}

package slimeknights.tconstruct.library.modifiers.fluid;

/**
 * Represents the level of a fluid effect
 * @param value  Effective level
 * @param max    Max level, used when dealing with conservative effects
 */
public record EffectLevel(float value, float max) {
  /**
   * Gets the effective amount given the existing amount. Can possibly be up to {@link #max()} by summing with {@link #value()}.
   * Used level will be {@code effective - existing}. If {@code effective <= existing}, no action need be performed.
   * @param existing  Existing level on the target, note you will likely want to rescale this from result to level units.
   * @return Effective effect level
   */
  public float effective(float existing) {
    return Math.min(this.value + existing, max);
  }

  /**
   * Gets the level that was used, given the cap exists
   * @param max  Maximum level that could have been set
   * @return  Level that was used.
   */
  public float computeUsed(float max) {
    return Math.min(this.value, max);
  }

  /** Check if the effect level is at least 1, used to limit effects that don't scale */
  public boolean isFull() {
    return value >= 1;
  }

  /** Divides the effect level by the given divisor */
  public EffectLevel divide(float divisor) {
    if (divisor == 1) {
      return this;
    }
    if (divisor == 0) {
      throw new IllegalArgumentException("Divisor cannot be zero");
    }
    return new EffectLevel(value / divisor, max / divisor);
  }

  /** Subtracts the given amount from the effect level */
  public EffectLevel subtract(float amount) {
    if (amount == 0) {
      return this;
    }
    return new EffectLevel(value - amount, max);
  }
}

package slimeknights.tconstruct.library.modifiers.fluid.entity;

import net.minecraft.core.RegistryAccess;
import net.minecraft.network.chat.Component;
import net.minecraft.world.entity.LivingEntity;
import net.minecraftforge.fluids.FluidStack;
import net.minecraftforge.fluids.capability.IFluidHandler.FluidAction;
import slimeknights.mantle.data.loadable.record.RecordLoadable;
import slimeknights.tconstruct.library.modifiers.fluid.EffectLevel;
import slimeknights.tconstruct.library.modifiers.fluid.FluidEffect;
import slimeknights.tconstruct.library.modifiers.fluid.FluidEffectContext;
import slimeknights.tconstruct.library.modifiers.fluid.FluidMobEffect;
import slimeknights.tconstruct.library.modifiers.fluid.TimeAction;

/**
 * Spilling effect to apply a potion effect
 * @param effect  Effect to apply
 * @param action  How the time scales
 * @see FluidMobEffect.Builder
 */
public record MobEffectFluidEffect(FluidMobEffect effect, TimeAction action) implements FluidEffect<FluidEffectContext.Entity> {
  public static final RecordLoadable<MobEffectFluidEffect> LOADER = RecordLoadable.create(
    FluidMobEffect.LOADABLE.directField(e -> e.effect),
    TimeAction.LOADABLE.requiredField("action", e -> e.action),
    MobEffectFluidEffect::new);

  @Override
  public RecordLoadable<MobEffectFluidEffect> getLoader() {
    return LOADER;
  }

  @Override
  public float apply(FluidStack fluid, EffectLevel scale, FluidEffectContext.Entity context, FluidAction action) {
    // first, need a target
    LivingEntity target = context.getLivingTarget();
    if (target != null) {
      return effect.apply(target, scale, this.action, action, context.getEffectSource());
    }
    return 0;
  }

  @Override
  public Component getDescription(RegistryAccess registryAccess) {
    return effect.getDisplayName(action);
  }
}

public float apply(LivingEntity target, EffectLevel scale, TimeAction timeAction, FluidAction action, @Nullable Entity source) {
  // infinite requires a full level
  if (isInfinite() && !scale.isFull()) {
    return 0;
  }
  float used;
  int time;
  // infinite costs 1 and sets the full time
  if (isInfinite()) {
    time = this.time;
    used = 1;
  } else {
    // add and set both have distinct behavior under an existing effect, same otherwise
    MobEffectInstance existingInstance = target.getEffect(effect);
    int amplifier = amplifier();
    if (existingInstance != null && existingInstance.getAmplifier() >= amplifier) {
      // if the existing level is larger, just skip, would be a cheese to increase said level
      // lower levels we treat as not having the effect, must be exact match to extend
      if (existingInstance.getAmplifier() > amplifier) {
        return 0;
      }
      if (timeAction == TimeAction.ADD) {
        int extraTime = (int) (this.time * scale.value());
        if (extraTime <= 0) {
          return 0;
        }
        // add simply sums existing time with the desired time. If the level is higher than ours, it produces a hidden effect
        time = existingInstance.getDuration() + extraTime;
        used = scale.value();
      } else {
        // set can produce time up to the maximum allowed by scale,
        float existing = existingInstance.getDuration() / (float) this.time;
        float effective = scale.effective(existing);
        // no change? means we skip applying entirely
        if (effective < existing) {
          return 0;
        }
        used = effective - existing;
        time = (int) (this.time * effective);
      }
    } else {
      // if no existing, time and set behave the same way, use maximum amount to compute time
      time = (int) (this.time * scale.value());
      used = scale.value();
    }
  }
  // if we got time, add the effect
  if (time != 0) {
    MobEffectInstance newInstance = effectWithTime(time);
    // if simulating, just ask if it's applicable. Won't handle event canceling, but thats acceptable.
    if (action.simulate()) {
      return target.canBeAffected(newInstance) ? used : 0;
    }
    return target.addEffect(newInstance, source) ? used : 0;
  }
  return 0;
}

public MobEffectInstance effectWithTime(int time) {
  MobEffectInstance instance = new MobEffectInstance(effect, time, this.level - 1);
  if (curativeItems != null) {
    instance.setCurativeItems(curativeItems.stream().map(ItemStack::new).collect(Collectors.toList()));
  }
  return instance;
}

public boolean isInfinite() {
  return time == MobEffectInstance.INFINITE_DURATION;
}

protected void onHitEntity(EntityHitResult result) {
  Entity target = result.getEntity();
  // apply knockback to the entity regardless of fluid type
  if (knockback > 0) {
    Vec3 vec3 = this.getDeltaMovement().multiply(1, 0, 1).normalize().scale(knockback * 0.6);
    if (vec3.lengthSqr() > 0) {
      target.push(vec3.x, 0.1, vec3.z);
    }
  }
  FluidStack fluid = getFluid();
  Level level = level();
  if (!level.isClientSide && !fluid.isEmpty()) {
    FluidEffects recipe = FluidEffectManager.INSTANCE.find(fluid.getFluid());
    if (recipe.hasEntityEffects()) {
      FluidEffectContext.Entity context = buildContext().location(result.getLocation()).target(target);
      int consumed = recipe.applyToEntity(fluid, power, context, FluidAction.EXECUTE);
      // update the stack
      if (consumed > 0) {
        updateCannonStack(context);
      }
      // shrink our internal fluid, means we get a crossbow piercing like effect if its not all used
      // discarding when empty ensures the fluid won't continue with the block effect
      // unlike blocks, failing is fine, means we just continue through to the block below the entity
      fluid.shrink(consumed);
      if (fluid.isEmpty()) {
        this.discard();
      } else {
        setFluid(fluid);
      }
    }
  }
}

private FluidEffectContext.Builder buildContext() {
  Level level = level();
  FluidEffectContext.Builder builder = FluidEffectContext.builder(level).projectile(this);
  Entity owner = getOwner();
  if (owner != null) {
    builder.user(owner);
  }
  if (this.cannon != null) {
    IItemHandler handler = getCannonInventory();
    if (handler != null) {
      builder.stack(handler.getStackInSlot(0).copy());
    }
  }
  return builder;
}

private void updateCannonStack(FluidEffectContext context) {
  if (cannon != null) {
    IItemHandlerModifiable handler = getCannonInventory();
    if (handler != null) {
      handler.setStackInSlot(0, context.getStack());
    }
  }
}

static void onTeleport(EntityTeleportEvent event) {
  if (event.getEntity() instanceof LivingEntity living && living.hasEffect(TinkerEffects.enderference.get())) {
    event.setCanceled(true);
  }
}

// ender - teleporting
LivingEntityPredicate hasReturning = new HasMobEffectPredicate(TinkerEffects.returning.get());
FluidMobEffect returningEffect = new FluidMobEffect(TinkerEffects.returning.get(), 7*20, 1, null);
addSlime(TinkerFluids.enderSlime)
  .addEntityEffects(FluidMobEffect.builder().effect(MobEffects.MOVEMENT_SLOWDOWN, 20*5).buildEntity(TimeAction.ADD))
  // if returning, extend it, need to do this first as otherwise we extend ourself
  .addEntityEffect(hasReturning, new MobEffectFluidEffect(returningEffect, TimeAction.ADD))
  // if no returning, give returning then teleport
  .addEntityEffect(hasReturning.inverted(), SequenceFluidEffect.entities().effect(new MobEffectFluidEffect(returningEffect, TimeAction.SET)).effect(new RandomTeleportFluidEffect(LevelingInt.eachLevel(8), LevelingInt.flat(16))).build())
  .addBlockEffect(SequenceFluidEffect.blocks().effect(new BreakBlockFluidEffect(0)).effect(new PlaceBlockFluidEffect(null)).build());

public int compute(float level) {
  return (int)(this.flat + this.eachLevel * level);
